Add-Type -AssemblyName System.Drawing
foreach ($img in $images) {
  $out = Join-Path $dir $img.n
  try {
    Invoke-WebRequest -Uri $img.u -OutFile $out -TimeoutSec 40 -UseBasicParsing
    $i = [System.Drawing.Image]::FromFile($out)
    "{0}: {1}x{2} ({3:N0} KB)" -f $img.n, $i.Width, $i.Height, ((Get-Item $out).Length / 1KB)
    $i.Dispose()
  } catch {
    "FAILED {0}: {1}" -f $img.n, $_.Exception.Message
  }
}
